const xml = items[0].json.data || items[0].json;
const text = typeof xml === 'string' ? xml : JSON.stringify(xml);
const stillProcessing = /<message>/.test(text) && !/<item /.test(text);
if (stillProcessing) return [{ json: { stillProcessing: true } }];

const itemRe = /<item[^>]*objectid="(\d+)"[^>]*>([\s\S]*?)<\/item>/g;
const nameRe = /<name[^>]*>([^<]*)<\/name>/;
const yearRe = /<yearpublished>([^<]*)<\/yearpublished>/;
const thumbRe = /<thumbnail>([^<]*)<\/thumbnail>/;
const avgRe = /<average value="([^"]*)"/;

const now = new Date().toISOString();
const games = [];
let m;
let n = 1;
while ((m = itemRe.exec(text))) {
  const id = m[1];
  const body = m[2];
  const nameMatch = body.match(nameRe);
  const yearMatch = body.match(yearRe);
  const thumbMatch = body.match(thumbRe);
  const avgMatch = body.match(avgRe);
  games.push({
    game_id: 'bgg-' + id,
    bgg_id: Number(id),
    num: n++,
    title: nameMatch ? nameMatch[1] : ('BGG #' + id),
    genre: '',
    type: '',
    desc: '',
    expansions: JSON.stringify([]),
    bgg_rating: avgMatch ? Number(avgMatch[1]) : null,
    photo_url: thumbMatch ? thumbMatch[1] : null,
    year: yearMatch ? yearMatch[1] : '',
    updated_at: now
  });
}
return [{ json: { stillProcessing: false, items: games } }];
